public void printCountdown(int n) {
    if (n == 0) {
        System.out.println("Liftoff!"); // Base Case
    } else {
        System.out.println(n);

        // THE RECURSIVE CASE
        // (n - 1) guarantees we are moving towards the Base Case of 0.
        printCountdown(n - 1); 
    }
}

// Mutual Recursion Example: Checking Even/Odd
public boolean isEven(int n) {
    if (n == 0) return true; // Base Case
    else return isOdd(n - 1); // Calls the other method
}

public boolean isOdd(int n) {
    if (n == 0) return false; // Base Case
    else return isEven(n - 1); // Calls the first method
}

// ❌ NOT TAIL RECURSIVE (Pending Math)
// The method must wait for factorial(n-1) to finish before it can multiply it by n.
public int factorial(int n) {
    if (n == 1) return 1;
    return n * factorial(n - 1); 
}

// ✅ TAIL RECURSIVE (Uses an Accumulator)
// The recursive call is the absolute last thing to happen.
public int tailFactorial(int n, int accumulator) {
    if (n == 1) return accumulator;
    return tailFactorial(n - 1, n * accumulator);
}

public int factorial(int n) {
    // 1. The Base Case: 0! and 1! both equal 1.
    if (n <= 1) {
        return 1;
    } 
    // 2. The Recursive Case: Multiply N by the factorial of N-1
    else {
        return n * factorial(n - 1);
    }
}

public int fibonacci(int n) {
    // Base Cases: The first two numbers in the sequence
    if (n == 0) return 0;
    if (n == 1) return 1;

    // Multi-Branch Recursive Case
    return fibonacci(n - 1) + fibonacci(n - 2);
}

public int gcd(int a, int b) {
    // Base Case: If the remainder reaches 0, 'a' is the Greatest Common Divisor.
    if (b == 0) {
        return a;
    } 
    // Recursive Case: Pass 'b' as the new 'a', and the remainder as the new 'b'.
    else {
        return gcd(b, a % b);
    }
}

public int binarySearch(int[] arr, int target, int low, int high) {
    // Base Case 1: The pointers crossed, meaning the target does NOT exist.
    if (low > high) return -1; 

    int mid = (low + high) / 2;

    // Base Case 2: Target found exactly at the middle!
    if (arr[mid] == target) return mid; 

    // Recursive Cases: Discard half the array and search the rest
    if (arr[mid] > target) {
        return binarySearch(arr, target, low, mid - 1); // Search Left Half
    } else {
        return binarySearch(arr, target, mid + 1, high); // Search Right Half
    }
}

public void solveHanoi(int numDisks, char source, char temp, char dest) {
    // Base Case: Only 1 disk left to move
    if (numDisks == 1) {
        System.out.println("Move disk from " + source + " to " + dest);
    } 
    // Recursive Case: The 3-Step Multi-Branch Strategy
    else {
        // Step 1: Move the stack of N-1 disks out of the way to the Temp peg
        solveHanoi(numDisks - 1, source, dest, temp); 

        // Step 2: Move the largest base disk directly to the Destination peg
        System.out.println("Move disk from " + source + " to " + dest);

        // Step 3: Move the N-1 stack from Temp onto the Destination peg
        solveHanoi(numDisks - 1, temp, source, dest); 
    }
}
